<?php session_start(); require __DIR__.'/../includes/db.php'; if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;} $uid=(int)$_SESSION['user_id']; if(isset($_POST['remove'])){$pid=(int)$_POST['remove'];$st=mysqli_prepare($conn,"DELETE FROM cart WHERE user_id=? AND product_id=?");mysqli_stmt_bind_param($st,'ii',$uid,$pid);mysqli_stmt_execute($st);} elseif(isset($_POST['qty']) && is_array($_POST['qty'])){foreach($_POST['qty'] as $pid=>$qty){$pid=(int)$pid;$qty=(int)$qty;if($qty<=0){$st=mysqli_prepare($conn,"DELETE FROM cart WHERE user_id=? AND product_id=?");mysqli_stmt_bind_param($st,'ii',$uid,$pid);mysqli_stmt_execute($st);continue;} $st=mysqli_prepare($conn,"SELECT stock FROM products WHERE id=?");mysqli_stmt_bind_param($st,'i',$pid);mysqli_stmt_execute($st);$p=mysqli_fetch_assoc(mysqli_stmt_get_result($st));$qty=min($qty,(int)($p['stock']??0));$st=mysqli_prepare($conn,"UPDATE cart SET quantity=? WHERE user_id=? AND product_id=?");mysqli_stmt_bind_param($st,'iii',$qty,$uid,$pid);mysqli_stmt_execute($st);}} header('Location: ../cart.php');exit; ?>